#include <deque>
#include <stdexcept>

class ThrowingType {
public:
    ThrowingType() = default;
    ThrowingType(const ThrowingType&) { 
        throw std::runtime_error("Copy failed"); 
    }
};

void test_push_front_exception(std::deque<ThrowingType>& d) {
    size_t initial_size = d.size();
    try {
        d.push_front(ThrowingType()); // Attempts copy, throws
    } catch (const std::exception&) {
        // Strong Guarantee: Deque size remains unchanged
        if (d.size() != initial_size) {
            // State corruption (should not happen)
        }
    }
    // pop_back() and pop_front() are guaranteed not to throw
    // d.pop_back(); 
}
